import React from "react";
import { useCurrentFrame, useVideoConfig, AbsoluteFill, spring, interpolate } from '../remotionShim';
import { makeLoadFont } from '../googleFonts';
const loadInter = makeLoadFont('Inter');

// Module-level font loading — delayRender/continueRender handled internally by loadFont()
const { fontFamily: interFamily } = loadInter();



export type MemoTearAnimationProps = Record<string, any>;

// Shared Memo Content rendered in both halves before clipping
const MemoCard: React.FC<{ s: number; title: string; amount: string }> = ({ s, title, amount }) => (
  <div
    style={{
      width: "100%",
      height: "100%",
      backgroundColor: "#f2f2f2",
      padding: `${50 * s}px ${40 * s}px`,
      display: "flex",
      flexDirection: "column",
      boxSizing: "border-box",
    }}
  >
    <div style={{ fontSize: 46 * s, fontWeight: 900, color: "#111", textAlign: "center", letterSpacing: 2 * s }}>
      {title}
    </div>
    <div style={{ width: "100%", height: 4 * s, backgroundColor: "#ccc", marginTop: 25 * s }} />
    <div style={{ width: "80%", height: 4 * s, backgroundColor: "#ccc", marginTop: 12 * s }} />

    <div
      style={{
        border: `${4 * s}px solid #111`,
        marginTop: 40 * s,
        padding: `${50 * s}px 0`,
        display: "flex",
        justifyContent: "center",
        alignItems: "center",
      }}
    >
      <div style={{ fontSize: 130 * s, fontWeight: 900, color: "#111", lineHeight: 1, letterSpacing: -2 * s }}>
        {amount}
      </div>
    </div>

    <div style={{ width: "100%", height: 4 * s, backgroundColor: "#ccc", marginTop: 40 * s }} />
    <div style={{ width: "90%", height: 4 * s, backgroundColor: "#ccc", marginTop: 12 * s }} />
    <div style={{ width: "60%", height: 4 * s, backgroundColor: "#ccc", marginTop: 12 * s }} />

    <div style={{ marginTop: "auto", display: "flex", justifyContent: "space-between", padding: `0 ${10 * s}px` }}>
      <svg width={110 * s} height={40 * s} viewBox="0 0 100 40">
        <path d="M5,25 C20,5 30,35 50,15 C60,5 70,30 90,20" fill="none" stroke="#111" strokeWidth={3 * s} />
        <line x1={0} y1={35} x2={100} y2={35} stroke="#bbb" strokeWidth={2 * s} />
      </svg>
      <svg width={110 * s} height={40 * s} viewBox="0 0 100 40">
        <path d="M10,20 C25,0 35,40 60,10 C70,0 80,35 95,15" fill="none" stroke="#111" strokeWidth={3 * s} />
        <line x1={0} y1={35} x2={100} y2={35} stroke="#bbb" strokeWidth={2 * s} />
      </svg>
    </div>
  </div>
);

const MemoTearAnimation: React.FC<MemoTearAnimationProps> = ({
  backgroundColor = "#0a0a0a",
  transparentBackground = false,
  durationInSeconds = 6,
  primaryColor = "#e5b879",
  backgroundYear = "2027",
  backgroundYearSize = 550,
  backgroundYearOpacity = 0.12,
  backgroundYearXOffset = 0,
  backgroundYearYOffset = 0,
  memoTitle = "DEAL MEMO",
  memoAmount = "$500",
}) => {
  const frame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();
  const s = Math.min(width, height) / 1080;

  const bgColor = transparentBackground ? `${backgroundColor}00` : backgroundColor;

  // Timings
  const tearStartFrame = fps * 2.5;

  // Entrance Springs
  const bgYearProgress = spring({ frame: frame - 5, fps, config: { damping: 14 } });
  const memoDropProgress = spring({ frame: frame - 25, fps, config: { damping: 13, mass: 1.2 } });

  // Tear Spring
  const tearProgress = spring({ frame: frame - tearStartFrame, fps, config: { damping: 14, mass: 1.1 } });

  // Interpolations
  const memoYOffset = interpolate(memoDropProgress, [0, 1], [-height * 1.2, 0]);

  const leftSepX = interpolate(tearProgress, [0, 1], [0, -90 * s]);
  const leftSepY = interpolate(tearProgress, [0, 1], [0, 40 * s]);
  const leftSepR = interpolate(tearProgress, [0, 1], [0, -10]);

  const rightSepX = interpolate(tearProgress, [0, 1], [0, 90 * s]);
  const rightSepY = interpolate(tearProgress, [0, 1], [0, 70 * s]);
  const rightSepR = interpolate(tearProgress, [0, 1], [0, 12]);

  // Jagged Clip Paths
  const jaggedPoints = [
    "50% 0%", "48% 6%", "52% 12%", "49% 18%", "53% 24%", "47% 30%", "51% 36%",
    "48% 42%", "52% 48%", "49% 54%", "54% 60%", "47% 66%", "51% 72%", "48% 78%",
    "53% 84%", "49% 90%", "50% 100%"
  ].join(", ");

  const leftClipPath = `polygon(0% 0%, ${jaggedPoints}, 0% 100%)`;
  const rightClipPath = `polygon(100% 0%, ${jaggedPoints}, 100% 100%)`;

  return (
    <AbsoluteFill style={{ backgroundColor: bgColor, fontFamily: interFamily, overflow: "hidden" }}>
      {/* Background Year */}
      <div
        style={{
          position: "absolute",
          left: "50%",
          top: "50%",
          transform: `translate(-50%, -50%) translate(${backgroundYearXOffset * s}px, ${backgroundYearYOffset * s}px) scale(${interpolate(bgYearProgress, [0, 1], [0.85, 1])})`,
          fontSize: backgroundYearSize * s,
          fontWeight: 900,
          color: primaryColor,
          opacity: interpolate(bgYearProgress, [0, 1], [0, 1]) * backgroundYearOpacity,
          lineHeight: 1,
          zIndex: 0,
          transition: "none",
          whiteSpace: "nowrap",
        }}
      >
        {backgroundYear}
      </div>

      {/* Centered Memo Animation Wrapper */}
      <div
        style={{
          position: "absolute",
          left: "50%",
          top: "50%",
          width: 540 * s,
          height: 720 * s,
          transform: `translate(-50%, -50%) translateY(${memoYOffset}px)`,
          filter: `drop-shadow(0px ${24 * s}px ${32 * s}px rgba(0,0,0,0.5))`,
          zIndex: 20,
          opacity: memoDropProgress === 0 ? 0 : 1, // fully hidden before entrance frame
          transition: "none",
        }}
      >
        {/* Left Torn Half */}
        <div
          style={{
            position: "absolute",
            left: 0,
            top: 0,
            width: "100%",
            height: "100%",
            transform: `translate(${leftSepX}px, ${leftSepY}px) rotate(${leftSepR}deg)`,
            transformOrigin: "center center",
            clipPath: leftClipPath,
            transition: "none",
          }}
        >
          <MemoCard s={s} title={memoTitle} amount={memoAmount} />
        </div>

        {/* Right Torn Half */}
        <div
          style={{
            position: "absolute",
            left: 0,
            top: 0,
            width: "100%",
            height: "100%",
            transform: `translate(${rightSepX}px, ${rightSepY}px) rotate(${rightSepR}deg)`,
            transformOrigin: "center center",
            clipPath: rightClipPath,
            transition: "none",
          }}
        >
          <MemoCard s={s} title={memoTitle} amount={memoAmount} />
        </div>
      </div>
    </AbsoluteFill>
  );
};

export default MemoTearAnimation;